#!/bin/sh
cd "$(dirname "$0")"
python3 -u survey9.py --fight 2/boss --pilot cole --frames 4200 --every 60 --mode boss --out survey/fzt --setup "window.__fzt = function(part, frac){   const b = boss, F = b && b._fz, H = b && b._mwBarrier;   if (!F || b.dead) return 'no rig';   if (F.phase === 'intro' || F.trans > 0) return 'wait ' + F.phase;   _dmgBullet = null;   if (part === 'shield') { if (!H || !H.active) return 'down'; _lastHitX = b.x; _lastHitY = b.y; hitBoss(H.hp); return 'shield broke'; }   if (H && H.active) return 'shield up';   const q = furnaceBoxes(b).find(c => c.key === part); if (!q) return 'no ' + part;   _lastHitX = q.x; _lastHitY = q.y;   hitBoss(Math.max(1, Math.ceil(F.pools[part] * (frac == null ? 1 : frac))));   return part + ' ' + F.pools[part] + ' ' + F.phase; };" '--event' "1100:window.__fzt('shield');" '--event' "1160:window.__fzt('left',0.6);" '--event' "1250:window.__fzt('right',0.6);" '--event' "1500:window.__fzt('left');" '--event' "1620:window.__fzt('right');" '--event' "2030:window.__fzt('shield');" '--event' "2100:window.__fzt('body',0.55);" '--event' "2760:window.__fzt('body');" '--event' "3250:window.__fzt('head',0.6);" '--event' "3620:window.__fzt('head');" --probe "({fz: boss&&boss._fz?[boss._fz.phase,+(boss._fz.trans||0).toFixed(2)]:null, hp: boss?Math.round(boss.hp)+'/'+Math.round(boss.maxhp):null, sh: boss&&boss._mwBarrier?!!boss._mwBarrier.active:null, dead: boss?!!boss.dead:null, st: state})" > survey_fzt.log 2>&1
